import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, AppState, InteractionManager, Modal, Pressable, ScrollView, SectionList, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import DateTimePicker from '@react-native-community/datetimepicker';
import Svg, { Circle } from 'react-native-svg';
import { SafeAreaView } from 'react-native-safe-area-context';
import BluecoinsDriveReader from 'bluecoins-drive-reader';
import type { TransactionDetection } from 'bluecoins-drive-reader';
import { refreshBluecoinsSummary, type BluecoinsSummary } from '../services/bluecoins';
import {
  applyEntryBalance, confirmRedCoinsExport, exportRedCoinsBackup, exportRedCoinsCsv, loadRedCoins, saveRedCoins,
  type RedCoinsAccountType, type RedCoinsEntry, type RedCoinsState, type RedCoinsType,
} from '../services/redcoins';

const C = { ink: '#111A2A', paper: '#FFF9EA', cream: '#F0E6D4', coral: '#F04444', mint: '#83D8B4', blue: '#528FF2', muted: '#7C8290', white: '#FFFFFF', gold: '#E7B84A' };
const money = (n = 0) => `RM ${Math.abs(n).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const dayKey = (value: string) => { const date = new Date(value); if (Number.isNaN(date.getTime())) return value.slice(0, 10); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; };
const entryTime = (value: string) => { const date = new Date(value); return Number.isNaN(date.getTime()) ? '--:--' : date.toLocaleTimeString('en-MY', { hour: '2-digit', minute: '2-digit', hour12: false }); };
const budgetKey = (category: string, subcategory: string) => `${category}\u0000${subcategory}`;
type Section = 'home' | 'activity' | 'accounts' | 'plan' | 'reports';

export default function RedCoinsScreen({ navigation, route }: any) {
  const [state, setState] = useState<RedCoinsState | null>(null);
  const [bluecoins, setBluecoins] = useState<BluecoinsSummary | null>(null);
  const [section, setSection] = useState<Section>('home');
  const [entryOpen, setEntryOpen] = useState(false);
  const [editingEntryId, setEditingEntryId] = useState<string | null>(null);
  const [entryDate, setEntryDate] = useState(new Date());
  const [manageOpen, setManageOpen] = useState<'account' | 'category' | 'sub' | null>(null);
  const [search, setSearch] = useState('');
  const [filterOpen, setFilterOpen] = useState(false);
  const [filterType, setFilterType] = useState<'all' | RedCoinsType>('all');
  const [filterAccount, setFilterAccount] = useState('all');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterDay, setFilterDay] = useState('');
  const [calendarCursor, setCalendarCursor] = useState(() => new Date());
  const [collapsedCards, setCollapsedCards] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [item, setItem] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<RedCoinsType>('expense');
  const [account, setAccount] = useState('');
  const [toAccount, setToAccount] = useState('');
  const [category, setCategory] = useState('');
  const [subcategory, setSubcategory] = useState('');
  const [note, setNote] = useState('');
  const [labels, setLabels] = useState('');
  const [repeat, setRepeat] = useState<RedCoinsEntry['repeat']>('none');
  const [installments, setInstallments] = useState('');
  const [advanced, setAdvanced] = useState(false);
  const [draftName, setDraftName] = useState('');
  const [draftType, setDraftType] = useState<RedCoinsAccountType>('Bank');
  const [draftBalance, setDraftBalance] = useState('0');
  const [draftCategory, setDraftCategory] = useState('');
  const [draftSub, setDraftSub] = useState('');
  const [draftParent, setDraftParent] = useState('');
  const [budgetEditor, setBudgetEditor] = useState<{ category: string; subcategory: string } | null>(null);
  const [budgetDraft, setBudgetDraft] = useState('');
  const [cycleBudgetDraft, setCycleBudgetDraft] = useState('');
  const [notificationAccess, setNotificationAccess] = useState(false);
  const [detections, setDetections] = useState<TransactionDetection[]>([]);
  const [reviewingDetectionId, setReviewingDetectionId] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      let summary: BluecoinsSummary | null = null;
      try { summary = await refreshBluecoinsSummary(); setBluecoins(summary); } catch {}
      const loaded = await loadRedCoins(summary);
      setState(loaded);
      setCycleBudgetDraft(String(loaded.monthlyBudget));
      const latest = loaded.entries.reduce<Date | null>((best, entry) => { const date = new Date(entry.date); return !best || date > best ? date : best; }, null);
      if (latest) setCalendarCursor(new Date(latest.getFullYear(), latest.getMonth(), 1));
    })();
  }, []);

  useEffect(() => {
    const refreshDetector = () => {
      BluecoinsDriveReader?.isNotificationAccessEnabledAsync?.().then(setNotificationAccess).catch(() => setNotificationAccess(false));
      BluecoinsDriveReader?.getTransactionDetectionsAsync?.().then(setDetections).catch(() => setDetections([]));
    };
    refreshDetector(); const subscription = AppState.addEventListener('change', (next) => { if (next === 'active') refreshDetector(); });
    return () => subscription.remove();
  }, []);

  useEffect(() => {
    const mode = route?.params?.mode;
    if (!state || !['expense', 'income', 'transfer'].includes(mode)) return;
    resetEntry(mode as RedCoinsType);
    if (route?.params?.item) setItem(String(route.params.item));
    if (route?.params?.amount) setAmount(String(route.params.amount));
    const hint = String(route?.params?.accountHint || '').trim().toLowerCase();
    if (hint) { const matched = state.accounts.find((candidate) => candidate.name.toLowerCase().includes(hint) || hint.includes(candidate.name.toLowerCase())); if (matched) setAccount(matched.name); }
    navigation.setParams({ mode: undefined, item: undefined, amount: undefined, accountHint: undefined, detected: undefined, fingerprint: undefined, source: undefined });
  }, [route?.params?.mode, route?.params?.fingerprint, state?.createdAt]);

  const persist = async (next: RedCoinsState) => { setState({ ...next }); await saveRedCoins(next); };
  const resetEntry = (initialType: RedCoinsType = 'expense') => {
    if (!state) return;
    const recent = state.entries.find((entry) => entry.type === initialType);
    const defaults = state.entryDefaults?.[initialType];
    setEditingEntryId(null);
    setReviewingDetectionId(null);
    setEntryDate(new Date());
    setItem(''); setAmount(''); setType(initialType); setAccount(defaults?.account || recent?.account || state.accounts.find((a) => a.type === 'Credit card')?.name || state.accounts[0]?.name || '');
    setToAccount(defaults?.toAccount || recent?.toAccount || ''); setCategory(defaults?.category || recent?.category || state.categories[0]?.name || 'General'); setSubcategory(defaults?.subcategory || recent?.subcategory || state.categories[0]?.subcategories[0] || 'General');
    setNote(''); setLabels(''); setRepeat('none'); setInstallments(''); setAdvanced(false); setEntryOpen(true);
  };
  const suggestions = useMemo(() => {
    const query = item.trim().toLowerCase();
    const stats = new Map<string, { entry: RedCoinsEntry; count: number; lastIndex: number }>();
    (state?.entries || []).forEach((entry, index) => { const key = entry.item.trim().toLowerCase(); if (!key) return; const current = stats.get(key); if (current) current.count += 1; else stats.set(key, { entry, count: 1, lastIndex: index }); });
    const own = [...stats.values()].filter(({ entry }) => !query || entry.item.toLowerCase().includes(query)).sort((a, b) => {
      const score = (name: string) => name === query ? 4 : name.startsWith(query) ? 3 : name.split(/\s+/).some((word) => word.startsWith(query)) ? 2 : 1;
      return (query ? score(b.entry.item.toLowerCase()) - score(a.entry.item.toLowerCase()) : 0) || b.count - a.count || a.lastIndex - b.lastIndex;
    }).slice(0, 6).map(({ entry, count }) => ({ ...entry, usageCount: count }));
    if (!query) return own;
    const imported = bluecoins?.monthly.fixedCommitmentOptions.filter((x) => x.label.toLowerCase().includes(query)).slice(0, 3).map((x, i) => ({ id: `blue-${i}`, item: x.label.split(' | ').pop() || x.label, amount: x.amount, account: '', category: x.category, subcategory: x.label.split(' | ')[0] || x.category, type: 'expense' as const, date: '', labels: [], usageCount: 0 })) || [];
    return [...own, ...imported].slice(0, 6);
  }, [item, state?.entries, bluecoins]);
  const applyEntryType = (nextType: RedCoinsType) => {
    setType(nextType); const defaults = state?.entryDefaults?.[nextType]; const recent = state?.entries.find((entry) => entry.type === nextType);
    if (defaults?.account || recent?.account) setAccount(defaults?.account || recent!.account);
    setToAccount(defaults?.toAccount || recent?.toAccount || '');
    if (nextType !== 'transfer') { setCategory(defaults?.category || recent?.category || category); setSubcategory(defaults?.subcategory || recent?.subcategory || subcategory); }
  };
  const chooseSuggestion = (entry: any) => { setItem(entry.item); if (entry.amount) setAmount(String(entry.amount)); applyEntryType(entry.type || 'expense'); if (entry.account) setAccount(entry.account); if (entry.toAccount) setToAccount(entry.toAccount); setCategory(entry.category); setSubcategory(entry.subcategory); };
  const editEntry = (entry: RedCoinsEntry) => {
    setReviewingDetectionId(null); setEditingEntryId(entry.id); setItem(entry.item); setAmount(String(entry.amount)); setType(entry.type); setAccount(entry.account); setToAccount(entry.toAccount || '');
    setEntryDate(new Date(entry.date));
    setCategory(entry.category); setSubcategory(entry.subcategory); setNote(entry.note || ''); setLabels((entry.labels || []).join(', ')); setRepeat(entry.repeat || 'none'); setInstallments(entry.installments ? String(entry.installments) : ''); setAdvanced(!!entry.note || !!entry.labels?.length || !!entry.repeat && entry.repeat !== 'none'); setEntryOpen(true);
  };
  const saveEntry = async () => {
    if (!state || !item.trim() || !Number(amount) || !account || (type === 'transfer' && !toAccount)) return Alert.alert('Incomplete entry', 'Add item, amount and account first.');
    const original = editingEntryId ? state.entries.find((entry) => entry.id === editingEntryId) : undefined;
    const entry: RedCoinsEntry = { id: original?.id || `${Date.now()}`, item: item.trim(), amount: Number(amount), type, account, toAccount: type === 'transfer' ? toAccount : undefined, category: type === 'transfer' ? '(Transfer)' : category, subcategory: type === 'transfer' ? '(Transfer)' : subcategory, date: entryDate.toISOString(), note: note.trim(), labels: labels.split(',').map((x) => x.trim()).filter(Boolean), status: original?.status || 'cleared', repeat, installments: Number(installments) || undefined, origin: original?.origin || 'redcoins', exportedAt: original?.exportedAt, editedAt: original?.origin === 'bluecoins' ? new Date().toISOString() : original?.editedAt };
    const next: RedCoinsState = { ...state, entries: original ? state.entries.map((row) => row.id === original.id ? entry : row) : [entry, ...state.entries], accounts: state.accounts.map((a) => ({ ...a })), entryDefaults: { ...(state.entryDefaults || {}), [type]: { account, toAccount: type === 'transfer' ? toAccount : undefined, category, subcategory } } };
    if (original) applyEntryBalance(next, original, -1);
    applyEntryBalance(next, entry, 1);
    setEntryOpen(false);
    if (reviewingDetectionId) dismissDetection(reviewingDetectionId).catch(() => {});
    InteractionManager.runAfterInteractions(() => {
      setSection('activity');
      setState(next);
      saveRedCoins(next).catch(() => Alert.alert('Save failed', 'The transaction is still visible, but LeanLog could not write it to local storage. Please try again.'));
    });
  };
  const deleteEditingEntry = () => {
    if (!state || !editingEntryId) return;
    const original = state.entries.find((entry) => entry.id === editingEntryId);
    if (!original) return;
    Alert.alert('Delete transaction?', `${original.item} · ${money(original.amount)}`, [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Delete', style: 'destructive', onPress: () => {
        const next = { ...state, entries: state.entries.filter((entry) => entry.id !== original.id), trash: [original, ...state.trash], accounts: state.accounts.map((entry) => ({ ...entry })) };
        applyEntryBalance(next, original, -1);
        setEntryOpen(false); setEditingEntryId(null); setState(next);
        InteractionManager.runAfterInteractions(() => saveRedCoins(next).catch(() => Alert.alert('Delete failed', 'LeanLog could not persist this change.')));
      } },
    ]);
  };
  const removeEntry = (entry: RedCoinsEntry) => Alert.alert('Move to Trash?', entry.item, [{ text: 'Cancel' }, { text: 'Move', style: 'destructive', onPress: async () => { if (!state) return; const next = { ...state, entries: state.entries.filter((e) => e.id !== entry.id), trash: [entry, ...state.trash], accounts: state.accounts.map((a) => ({ ...a })) }; applyEntryBalance(next, entry, -1); await persist(next); } }]);

  const searchIndex = useMemo(() => new Map((state?.entries || []).map((entry) => [entry.id, `${entry.item}\u0000${entry.category}\u0000${entry.subcategory}\u0000${entry.account}\u0000${entry.toAccount || ''}\u0000${entry.note || ''}`.toLowerCase()])), [state?.entries]);
  const filtered = useMemo(() => {
    if (!state) return [];
    const needle = search.trim().toLowerCase();
    return state.entries.filter((entry) => {
      if (filterType !== 'all' && entry.type !== filterType) return false;
      if (filterAccount !== 'all' && entry.account !== filterAccount) return false;
      if (filterCategory !== 'all' && entry.category !== filterCategory) return false;
      if (filterDay && dayKey(entry.date) !== filterDay) return false;
      if (!needle) return true;
      return searchIndex.get(entry.id)?.includes(needle);
    }).sort((a, b) => {
      const time = new Date(b.date).getTime() - new Date(a.date).getTime();
      return time || b.id.localeCompare(a.id, undefined, { numeric: true });
    });
  }, [state, search, searchIndex, filterType, filterAccount, filterCategory, filterDay]);
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const entryBalanceById = useMemo(() => {
    if (!state) return new Map<string, number>();
    const balances = new Map(state.accounts.map((account) => [account.name, account.balance]));
    const result = new Map<string, number>();
    [...state.entries].sort((a, b) => b.date.localeCompare(a.date)).forEach((entry) => {
      result.set(entry.id, balances.get(entry.account) || 0);
      if (entry.type === 'expense') balances.set(entry.account, (balances.get(entry.account) || 0) + entry.amount);
      if (entry.type === 'income') balances.set(entry.account, (balances.get(entry.account) || 0) - entry.amount);
      if (entry.type === 'transfer') {
        balances.set(entry.account, (balances.get(entry.account) || 0) + entry.amount);
        if (entry.toAccount) balances.set(entry.toAccount, (balances.get(entry.toAccount) || 0) - entry.amount);
      }
    });
    return result;
  }, [state]);
  const activitySections = useMemo(() => {
    const groups = new Map<string, RedCoinsEntry[]>();
    filtered.forEach((entry) => { const key = dayKey(entry.date); const rows = groups.get(key); if (rows) rows.push(entry); else groups.set(key, [entry]); });
    return [...groups].map(([date, data]) => ({
      date,
      title: new Date(`${date}T12:00:00`).toLocaleDateString('en-MY', { weekday: 'short', day: 'numeric', month: 'long', year: 'numeric' }).toUpperCase(),
      total: data.reduce((sum, entry) => sum + (entry.type === 'expense' ? -entry.amount : entry.type === 'income' ? entry.amount : 0), 0),
      data,
    }));
  }, [filtered]);
  const selectedTotal = useMemo(() => {
    if (!state || selectedSet.size === 0) return 0;
    return state.entries.reduce((sum, entry) => selectedSet.has(entry.id) ? sum + (entry.type === 'expense' ? -entry.amount : entry.type === 'income' ? entry.amount : 0) : sum, 0);
  }, [state, selectedSet]);
  const toggleSelected = useCallback((entry: RedCoinsEntry) => setSelectedIds((ids) => ids.includes(entry.id) ? ids.filter((id) => id !== entry.id) : [...ids, entry.id]), []);
  const openDashboardFilter = (kind: 'day' | 'category' | 'account', value: string) => {
    setSearch(''); setSelectedIds([]); setFilterType('all');
    setFilterDay(kind === 'day' ? value : '');
    setFilterCategory(kind === 'category' ? value : 'all');
    setFilterAccount(kind === 'account' ? value : 'all');
    setSection('activity');
  };
  const applyLedgerFilters = useCallback((next: { type: 'all' | RedCoinsType; account: string; category: string; day: string }) => {
    setFilterOpen(false);
    InteractionManager.runAfterInteractions(() => { setFilterType(next.type); setFilterAccount(next.account); setFilterCategory(next.category); setFilterDay(next.day); });
  }, []);
  const toggleCard = (name: string) => setCollapsedCards((cards) => cards.includes(name) ? cards.filter((card) => card !== name) : [...cards, name]);
  const dismissDetection = async (id: string) => { await BluecoinsDriveReader?.dismissTransactionDetectionAsync?.(id); setDetections((rows) => rows.filter((row) => row.id !== id)); };
  const reviewDetection = (detection: TransactionDetection) => {
    resetEntry(); setReviewingDetectionId(detection.id); setType('expense'); setItem(detection.merchant); setAmount(String(detection.amount));
    const hint = detection.accountHint.toLowerCase();
    if (hint) { const matched = state?.accounts.find((candidate) => candidate.name.toLowerCase().includes(hint) || hint.includes(candidate.name.toLowerCase())); if (matched) setAccount(matched.name); }
  };
  const runDetectorTest = async () => {
    if (!BluecoinsDriveReader?.createTestTransactionDetectionAsync) return Alert.alert('Build required', 'The detector inbox needs the next native APK build.');
    const row = await BluecoinsDriveReader.createTestTransactionDetectionAsync(); setDetections((current) => [row, ...current.filter((item) => item.id !== row.id)]);
  };
  const budgetCategories = useMemo(() => {
    if (!state) return [];
    const pairTypes = new Map<string, Set<RedCoinsType>>();
    state.entries.forEach((entry) => {
      const key = budgetKey(entry.category, entry.subcategory); const types = pairTypes.get(key) || new Set<RedCoinsType>(); types.add(entry.type); pairTypes.set(key, types);
    });
    const reserved = /^\((?:new account|no category|transfer)\)$/i;
    return state.categories.map((group) => ({ ...group, subcategories: group.subcategories.filter((subcategory) => {
      if (reserved.test(group.name.trim()) || reserved.test(subcategory.trim())) return false;
      const types = pairTypes.get(budgetKey(group.name, subcategory));
      return !types || types.has('expense');
    }) })).filter((group) => group.subcategories.length > 0);
  }, [state?.categories, state?.entries]);
  const budgetKeys = useMemo(() => new Set(budgetCategories.flatMap((group) => group.subcategories.map((subcategory) => budgetKey(group.name, subcategory)))), [budgetCategories]);

  if (!state) return <SafeAreaView style={s.loading}><Text style={s.loadingText}>Opening your money room…</Text></SafeAreaView>;

  const now = new Date(); const cycleStart = new Date(now.getFullYear(), now.getMonth() - (now.getDate() < state.payday ? 1 : 0), state.payday); const cycleRows = state.entries.filter((e) => new Date(e.date) >= cycleStart); const spent = cycleRows.filter((e) => e.type === 'expense').reduce((sum, e) => sum + e.amount, 0); const income = cycleRows.filter((e) => e.type === 'income').reduce((sum, e) => sum + e.amount, 0); const remaining = state.monthlyBudget - spent; const daysLeft = Math.max(1, Math.ceil((new Date(cycleStart.getFullYear(), cycleStart.getMonth() + 1, state.payday).getTime() - now.getTime()) / 86400000)); const cardDebt = state.accounts.filter((a) => a.type === 'Credit card').reduce((sum, a) => sum + Math.max(0, -a.balance), 0); const cash = state.accounts.filter((a) => ['Bank', 'Cash'].includes(a.type)).reduce((sum, a) => sum + a.balance, 0); const trueSpendable = Math.min(remaining - state.safetyBuffer, cash - cardDebt);
  const catSpend = cycleRows.filter((e) => e.type === 'expense').reduce<Record<string, number>>((map, e) => ({ ...map, [e.category]: (map[e.category] || 0) + e.amount }), {}); const topCats = Object.entries(catSpend).sort((a, b) => b[1] - a[1]);
  const allocatedBudget = Object.entries(state.subcategoryBudgets || {}).reduce((sum, [key, value]) => sum + (budgetKeys.has(key) ? Math.max(0, Number(value) || 0) : 0), 0);
  const unallocatedBudget = state.monthlyBudget - allocatedBudget;
  const subcategorySpend = cycleRows.filter((entry) => entry.type === 'expense').reduce<Record<string, number>>((map, entry) => ({ ...map, [budgetKey(entry.category, entry.subcategory)]: (map[budgetKey(entry.category, entry.subcategory)] || 0) + entry.amount }), {});
  const categoryBudget = (category: string) => budgetCategories.find((group) => group.name === category)?.subcategories.reduce((sum, subcategory) => sum + (state.subcategoryBudgets[budgetKey(category, subcategory)] || 0), 0) || 0;
  const openBudgetEditor = (category: string, subcategory: string) => { setBudgetEditor({ category, subcategory }); setBudgetDraft(String(state.subcategoryBudgets[budgetKey(category, subcategory)] || '')); };
  const saveSubcategoryBudget = async () => {
    if (!budgetEditor) return;
    const amountValue = Math.max(0, Number(budgetDraft) || 0); const key = budgetKey(budgetEditor.category, budgetEditor.subcategory); const current = state.subcategoryBudgets[key] || 0; const available = Math.max(0, state.monthlyBudget - (allocatedBudget - current));
    if (amountValue > available) return Alert.alert('Not enough budget left', `Only ${money(available)} is unallocated. Reduce another subcategory budget or increase the salary-cycle budget first.`);
    const nextBudgets = { ...state.subcategoryBudgets }; if (amountValue > 0) nextBudgets[key] = amountValue; else delete nextBudgets[key];
    await persist({ ...state, subcategoryBudgets: nextBudgets }); setBudgetEditor(null);
  };
  const saveCycleBudget = async () => {
    const nextValue = Math.max(0, Number(cycleBudgetDraft) || 0);
    if (nextValue < allocatedBudget) { setCycleBudgetDraft(String(state.monthlyBudget)); return Alert.alert('Budget already allocated', `${money(allocatedBudget)} is already assigned to subcategories. The cycle budget cannot be lower than that.`); }
    await persist({ ...state, monthlyBudget: nextValue }); setCycleBudgetDraft(String(nextValue));
  };

  const Home = () => {
    const today = new Date();
    const anchor = state.entries.length ? new Date(Math.max(...state.entries.map((entry) => new Date(entry.date).getTime()))) : today;
    const weekDays = Array.from({ length: 7 }, (_, offset) => { const date = new Date(anchor); date.setDate(anchor.getDate() - (6 - offset)); const key = dayKey(date.toISOString()); return { key, label: date.toLocaleDateString('en-MY', { weekday: 'short' }), amount: state.entries.filter((e) => e.type === 'expense' && dayKey(e.date) === key).reduce((sum, e) => sum + e.amount, 0) }; });
    const weekMax = Math.max(1, ...weekDays.map((day) => day.amount));
    const lastThirtyStart = new Date(anchor); lastThirtyStart.setDate(anchor.getDate() - 29); lastThirtyStart.setHours(0, 0, 0, 0);
    const thirtyAverage = state.entries.filter((entry) => entry.type === 'expense' && new Date(entry.date) >= lastThirtyStart && new Date(entry.date) <= anchor).reduce((sum, entry) => sum + entry.amount, 0) / 30;
    const calendarStart = new Date(calendarCursor.getFullYear(), calendarCursor.getMonth(), 1); const leading = calendarStart.getDay();
    const calendar = Array.from({ length: 42 }, (_, index) => { const date = new Date(calendarCursor.getFullYear(), calendarCursor.getMonth(), 1 - leading + index); const key = dayKey(date.toISOString()); const types = new Set(state.entries.filter((entry) => dayKey(entry.date) === key).map((entry) => entry.type)); return { key, date, types, muted: date.getMonth() !== calendarCursor.getMonth() }; });
    const months = Array.from({ length: 3 }, (_, offset) => { const date = new Date(anchor.getFullYear(), anchor.getMonth() - (2 - offset), 1); const rows = state.entries.filter((e) => { const value = new Date(e.date); return value.getFullYear() === date.getFullYear() && value.getMonth() === date.getMonth(); }); return { label: date.toLocaleDateString('en-MY', { month: 'short' }), incoming: rows.filter((e) => e.type === 'income').reduce((sum, e) => sum + e.amount, 0), outgoing: rows.filter((e) => e.type === 'expense').reduce((sum, e) => sum + e.amount, 0) }; });
    const flowMax = Math.max(1, ...months.flatMap((month) => [month.incoming, month.outgoing]));
    const palette = [C.coral, C.blue, '#18A879', C.gold, '#D943A8', '#8457C8'];
    const budgetSegments = topCats.slice(0, 6).map(([name, value], index) => ({ name, value, color: palette[index], percent: spent ? value / spent * 100 : 0 }));
    const favoriteAccounts = state.accounts.filter((account) => ['Bank', 'Cash', 'Credit card'].includes(account.type)).slice(0, 6);
    return <>
      <View style={s.dashboardIntro}><View><Text style={s.eyebrow}>REDCOINS / SALARY CYCLE</Text><Text style={s.dashboardTitle}>Your money, clearly.</Text></View><Text style={s.dashboardDate}>{today.toLocaleDateString('en-MY', { day: 'numeric', month: 'short' })}</Text></View>
      <View style={s.dashCard}><TouchableOpacity style={s.dashHeadRow} onPress={() => toggleCard('daily')}><Text style={s.dashHead}>Daily Summary</Text><Ionicons name={collapsedCards.includes('daily') ? 'chevron-forward' : 'chevron-down'} size={16} color={C.ink} /></TouchableOpacity>{!collapsedCards.includes('daily') && <><View style={s.weekBars}>{weekDays.map((day) => <TouchableOpacity key={day.key} style={s.weekDay} onPress={() => openDashboardFilter('day', day.key)}><Text style={s.weekAmount}>{day.amount ? `RM${day.amount.toFixed(0)}` : '—'}</Text><View style={[s.weekBar, { height: Math.max(3, day.amount / weekMax * 92) }]} /><Text style={s.weekLabel}>{day.label}</Text></TouchableOpacity>)}</View><View style={s.summaryLine}><Text style={s.summaryMuted}>7 days average <Text style={s.summaryExpense}>{money(weekDays.reduce((sum, day) => sum + day.amount, 0) / 7)}</Text></Text><Text style={s.summaryMuted}>30 days average <Text style={s.summaryExpense}>{money(thirtyAverage)}</Text></Text></View></>}</View>
      <View style={s.dashCard}><View style={s.calendarHead}><TouchableOpacity style={s.calendarArrow} onPress={() => setCalendarCursor((value) => new Date(value.getFullYear(), value.getMonth() - 1, 1))}><Ionicons name="chevron-back" size={17} color={C.ink} /></TouchableOpacity><Text style={s.dashHead}>{calendarCursor.toLocaleDateString('en-MY', { month: 'long', year: 'numeric' })}</Text><TouchableOpacity style={s.calendarArrow} onPress={() => setCalendarCursor((value) => new Date(value.getFullYear(), value.getMonth() + 1, 1))}><Ionicons name="chevron-forward" size={17} color={C.ink} /></TouchableOpacity></View><View style={s.calendarGrid}>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((label) => <Text key={label} style={s.calendarWeek}>{label}</Text>)}{calendar.map((day) => <TouchableOpacity key={day.key} onPress={() => openDashboardFilter('day', day.key)} style={[s.calendarDay, day.key === dayKey(today.toISOString()) && s.calendarToday, day.muted && { opacity: .3 }]}><Text style={s.calendarNumber}>{day.date.getDate()}</Text><View style={s.calendarDots}>{day.types.has('expense') && <View style={[s.calendarDot, { backgroundColor: C.coral }]} />}{day.types.has('income') && <View style={[s.calendarDot, { backgroundColor: '#18A879' }]} />}{day.types.has('transfer') && <View style={[s.calendarDot, { backgroundColor: C.blue }]} />}</View></TouchableOpacity>)}</View><View style={s.calendarKey}><Text style={s.calendarKeyText}>● Expense</Text><Text style={[s.calendarKeyText, { color: '#18A879' }]}>● Income</Text><Text style={[s.calendarKeyText, { color: C.blue }]}>● Transfer</Text></View></View>
      <View style={s.dashCard}><TouchableOpacity style={s.dashHeadRow} onPress={() => toggleCard('budget')}><Text style={s.dashHead}>Budget Summary</Text><Ionicons name={collapsedCards.includes('budget') ? 'chevron-forward' : 'chevron-down'} size={16} color={C.ink} /></TouchableOpacity>{!collapsedCards.includes('budget') && <><View style={s.budgetSummary}><BudgetDonut segments={budgetSegments} spent={spent} /><View style={{ flex: 1 }}>{budgetSegments.map((segment) => <TouchableOpacity key={segment.name} style={s.legendRow} onPress={() => openDashboardFilter('category', segment.name)}><View style={[s.legendDot, { backgroundColor: segment.color }]} /><Text style={s.legendName} numberOfLines={1}>{segment.name}</Text><Text style={s.legendValue}>{segment.percent.toFixed(0)}%</Text></TouchableOpacity>)}</View></View><View style={s.budgetTrack}><View style={[s.budgetFill, { width: `${Math.min(100, spent / Math.max(1, state.monthlyBudget) * 100)}%` }]} /></View><View style={s.summaryLine}><Text style={s.summaryExpense}>{Math.round(spent / Math.max(1, state.monthlyBudget) * 100)}% · {money(spent)}</Text><Text style={s.summaryMuted}>{remaining < 0 ? `${money(Math.abs(remaining))} over` : `${money(remaining)} remaining`}</Text></View></>}</View>
      <View style={s.dashCard}><TouchableOpacity style={s.dashHeadRow} onPress={() => toggleCard('favorites')}><Text style={s.dashHead}>Favorite Accounts</Text><Ionicons name={collapsedCards.includes('favorites') ? 'chevron-forward' : 'chevron-down'} size={16} color={C.ink} /></TouchableOpacity>{!collapsedCards.includes('favorites') && <>{favoriteAccounts.map((account) => <TouchableOpacity key={account.id} style={s.favoriteRow} onPress={() => openDashboardFilter('account', account.name)}><Text style={s.favoriteName}>{account.name}</Text><Text style={[s.favoriteBalance, account.balance < 0 && { color: C.coral }]}>{account.balance < 0 ? '− ' : ''}{money(account.balance)}</Text></TouchableOpacity>)}<Text style={s.favoriteTotal}>Total: {money(favoriteAccounts.reduce((sum, account) => sum + account.balance, 0))}</Text><TouchableOpacity style={s.balanceSheetButton} onPress={() => setSection('accounts')}><Text style={s.balanceSheetText}>BALANCE SHEET</Text></TouchableOpacity></>}</View>
      <View style={s.dashCard}><Text style={s.dashHead}>Cash Flow</Text><View style={s.cashflowChart}>{months.map((month) => <View key={month.label} style={s.cashMonth}><View style={s.cashBars}><View style={[s.cashBar, { height: Math.max(3, month.outgoing / flowMax * 110), backgroundColor: C.coral }]} /><View style={[s.cashBar, { height: Math.max(3, month.incoming / flowMax * 110), backgroundColor: '#18A879' }]} /></View><Text style={s.weekLabel}>{month.label}</Text></View>)}</View></View>
      <View style={s.hero}><Text style={s.kicker}>TRUE SPENDABLE</Text><Text style={[s.heroMoney, trueSpendable < 0 && { color: '#FF8069' }]}>{trueSpendable < 0 ? '− ' : ''}{money(trueSpendable)}</Text><Text style={s.heroSub}>Budget left {money(remaining)} · cash after cards {money(cash - cardDebt)}</Text><View style={s.formula}><Mini label="CASH" value={cash} /><Mini label="CARD OWED" value={-cardDebt} /><Mini label="SAFE/DAY" value={Math.max(0, remaining) / daysLeft} /></View></View>
    </>;
  };
  const activityHeader = <View style={s.activityHeader}>
    {selectedIds.length > 0 && <View style={s.selectedTotal}><Text style={s.selectedTotalText}>{selectedTotal < 0 ? '− ' : '+ '}{money(selectedTotal)}</Text><Text style={s.selectedTotalMeta}>{selectedIds.length} selected</Text></View>}
    <View style={s.ledgerTools}><LedgerSearch value={search} onChange={setSearch} /><TouchableOpacity style={s.filterButton} onPress={() => setFilterOpen(true)}><Ionicons name="options" size={17} color={C.white} /></TouchableOpacity></View>
    {selectedIds.length > 0 && <View style={s.selectionBar}><Text style={s.selectionCount}>{selectedIds.length} selected</Text><TouchableOpacity onPress={() => setSelectedIds(filtered.map((e) => e.id))}><Text style={s.selectionLink}>SELECT ALL</Text></TouchableOpacity><TouchableOpacity onPress={() => setSelectedIds([])}><Text style={s.selectionLink}>CLOSE</Text></TouchableOpacity></View>}
  </View>;
  const filterModal = <LedgerFilterModal visible={filterOpen} current={{ type: filterType, account: filterAccount, category: filterCategory, day: filterDay }} accounts={state.accounts.map((entry) => entry.name)} categories={state.categories.map((entry) => entry.name)} close={() => setFilterOpen(false)} apply={applyLedgerFilters} />;
  const Accounts = () => { const pending = state.entries.filter((e) => e.origin === 'redcoins' && !e.exportedAt); const awaiting = [...(state.exportBatches || [])].reverse().find((batch) => !batch.confirmedAt); const runExport = async (mode: 'pending' | 'all') => { const batch = await exportRedCoinsCsv(state, mode); if (!batch) return Alert.alert('Nothing new to export', 'Every RedCoins entry is already marked as imported.'); await persist({ ...state, exportBatches: [batch, ...(state.exportBatches || [])] }); }; return <><Title eyebrow="MONEY LIBRARY" title="Your structure, your rules." action="＋ Account" onAction={() => { setDraftName(''); setDraftBalance('0'); setManageOpen('account'); }} /><View style={s.accountGrid}>{state.accounts.map((a) => <View key={a.id} style={[s.accountCard, a.type === 'Credit card' && s.dark]}><Text style={s.accountType}>{a.type.toUpperCase()}</Text><Text style={[s.accountName, a.type === 'Credit card' && { color: C.paper }]}>{a.name}</Text><Text style={[s.accountBalance, a.balance < 0 && { color: '#FF8069' }]}>{a.balance < 0 ? '− ' : ''}{money(a.balance)}</Text></View>)}</View><Title eyebrow="CATEGORIES" title="Built around your life." action="＋ Category" onAction={() => { setDraftCategory(''); setDraftSub(''); setManageOpen('category'); }} />{state.categories.map((c) => <View key={c.id} style={s.categoryCard}><View style={{ flex: 1 }}><Text style={s.categoryName}>{c.icon} {c.name}</Text><Text style={s.categorySubs}>{c.subcategories.join(' · ')}</Text></View><TouchableOpacity onPress={() => { setDraftParent(c.name); setDraftSub(''); setManageOpen('sub'); }} style={s.smallButton}><Text style={s.smallButtonText}>＋ SUB</Text></TouchableOpacity></View>)}<Title eyebrow="AUTOMATION" title="What comes back." /><View style={s.card}>{state.entries.filter((e) => e.repeat && e.repeat !== 'none').slice(0, 8).map((e) => <EntryRow key={e.id} entry={e} />)}{!state.entries.some((e) => e.repeat && e.repeat !== 'none') && <Empty text="No scheduled RedCoins entries yet." />}</View><Title eyebrow="DATA BRIDGE" title="RedCoins → Bluecoins." /><View style={s.exportCard}><Text style={s.exportTitle}>Weekly hand-off</Text><Text style={s.exportCopy}>{pending.length} new entries since the last confirmed import. Bluecoins baseline history is never exported again.</Text><TouchableOpacity style={s.exportPrimary} onPress={() => runExport('pending')}><Text style={s.exportPrimaryText}>EXPORT {pending.length} NEW ENTRIES</Text></TouchableOpacity>{awaiting && <TouchableOpacity style={s.confirmImport} onPress={async () => persist(confirmRedCoinsExport(state, awaiting.id))}><Ionicons name="checkmark-circle" size={17} color={C.ink} /><Text style={s.confirmImportText}>MARK {awaiting.entryIds.length} AS IMPORTED</Text></TouchableOpacity>}<TouchableOpacity style={s.exportSecondary} onPress={() => runExport('all')}><Text style={s.exportSecondaryText}>EXPORT ALL REDCOINS ENTRIES</Text></TouchableOpacity><TouchableOpacity style={s.exportSecondary} onPress={() => exportRedCoinsBackup(state)}><Text style={s.exportSecondaryText}>BACKUP REDCOINS</Text></TouchableOpacity></View><Title eyebrow="EXPORT HISTORY" title="What crossed over." /><View style={s.card}>{(state.exportBatches || []).slice(0, 6).map((batch) => <View key={batch.id} style={s.commitRow}><View><Text style={s.entryName}>{batch.entryIds.length} entries</Text><Text style={s.entryMeta}>{new Date(batch.createdAt).toLocaleString('en-MY')}</Text></View><Text style={[s.exportStatus, batch.confirmedAt && { color: '#379B73' }]}>{batch.confirmedAt ? 'IMPORTED' : 'AWAITING'}</Text></View>)}{!state.exportBatches?.length && <Empty text="No export batches yet." />}</View><Title eyebrow="RECOVERY" title="Trash." /> <View style={s.card}>{state.trash.map((entry) => <View key={entry.id} style={s.trashRow}><View style={{ flex: 1 }}><Text style={s.entryName}>{entry.item}</Text><Text style={s.entryMeta}>{money(entry.amount)} · {entry.date.slice(0,10)}</Text></View><TouchableOpacity style={s.restoreButton} onPress={async () => { const next = { ...state, trash: state.trash.filter((e) => e.id !== entry.id), entries: [entry, ...state.entries], accounts: state.accounts.map((a) => ({ ...a })) }; applyEntryBalance(next, entry, 1); await persist(next); }}><Text style={s.restoreText}>RESTORE</Text></TouchableOpacity></View>)}{!state.trash.length && <Empty text="Trash is empty." />}</View></>; };
  const Plan = () => <><Title eyebrow="SALARY-CYCLE PLAN" title="Give every ringgit a job." />
    <View style={s.detectorCard}><View style={[s.detectorIcon, notificationAccess && { backgroundColor: C.mint }]}><Ionicons name={notificationAccess ? 'notifications' : 'notifications-off'} size={20} color={C.ink} /></View><View style={{ flex: 1 }}><Text style={s.detectorTitle}>Transaction detector</Text><Text style={s.detectorCopy}>{notificationAccess ? 'Active · eligible payment alerts are checked locally.' : 'Enable Notification access to catch eligible payments.'}</Text></View><TouchableOpacity style={[s.detectorButton, notificationAccess && { backgroundColor: '#DDF1E7' }]} onPress={() => BluecoinsDriveReader?.openNotificationAccessSettingsAsync?.().catch(() => Alert.alert('Unavailable', 'Notification access settings could not be opened on this device.'))}><Text style={s.detectorButtonText}>{notificationAccess ? 'MANAGE' : 'ENABLE'}</Text></TouchableOpacity></View><Text style={s.detectorPrivacy}>OTP, TAC and login alerts are ignored. Notification text never leaves this phone.</Text>
    <View style={s.detectorInbox}><View style={s.detectorInboxHead}><View><Text style={s.eyebrow}>DETECTOR INBOX</Text><Text style={s.detectorInboxTitle}>{detections.length ? `${detections.length} waiting for review` : 'Nothing waiting'}</Text></View><TouchableOpacity style={s.detectorTest} onPress={runDetectorTest}><Text style={s.detectorTestText}>RUN TEST</Text></TouchableOpacity></View>{detections.slice(0, 10).map((detection) => <View key={detection.id} style={s.detectionRow}><View style={s.detectionAmount}><Text style={s.detectionAmountText}>{money(detection.amount)}</Text></View><View style={{ flex: 1 }}><Text style={s.detectionMerchant} numberOfLines={1}>{detection.merchant}</Text><Text style={s.detectionMeta} numberOfLines={1}>{new Date(detection.createdAt).toLocaleString('en-MY')} · {detection.accountHint || detection.source}</Text></View><TouchableOpacity style={s.detectionReview} onPress={() => reviewDetection(detection)}><Text style={s.detectionReviewText}>REVIEW</Text></TouchableOpacity><TouchableOpacity onPress={() => dismissDetection(detection.id)}><Ionicons name="close-circle" size={20} color={C.muted} /></TouchableOpacity></View>)}{!detections.length && <Text style={s.detectorEmpty}>A matching bank, wallet or SMS notification will appear here before you save it as a transaction.</Text>}</View>
    <View style={s.planHero}><PlanCell label="CYCLE SPEND" value={spent} /><PlanCell label="SPENDABLE LEFT" value={remaining} /><PlanCell label="PROJECTED" value={spent / Math.max(1, new Date().getDate()) * 30} /></View>
    <View style={s.card}><Text style={s.cardTitle}>Budget pool</Text><View style={s.budgetPoolRow}><Mini label="CYCLE CEILING" value={state.monthlyBudget} /><Mini label="ALLOCATED" value={allocatedBudget} /><Mini label="UNALLOCATED" value={unallocatedBudget} /></View><View style={s.budgetTrack}><View style={[s.budgetFill, { width: `${Math.min(100, allocatedBudget / Math.max(1, state.monthlyBudget) * 100)}%`, backgroundColor: allocatedBudget > state.monthlyBudget ? C.coral : C.blue }]} /></View><Text style={s.poolHint}>Subcategory budgets share this one pool. Category totals are calculated automatically.</Text></View>
    <View style={s.card}><Text style={s.cardTitle}>Plan controls</Text><View style={s.cycleBudgetEdit}><View style={{ flex: 1 }}><Field label="SALARY-CYCLE BUDGET" value={cycleBudgetDraft} onChange={setCycleBudgetDraft} numeric /></View><TouchableOpacity style={s.cycleSave} onPress={saveCycleBudget}><Text style={s.cycleSaveText}>UPDATE</Text></TouchableOpacity></View><Field label="PAYDAY (1—28)" value={String(state.payday)} onChange={async (v: string) => persist({ ...state, payday: Math.max(1, Math.min(28, Number(v) || 25)) })} numeric /><Field label="SAFETY BUFFER" value={String(state.safetyBuffer)} onChange={async (v: string) => persist({ ...state, safetyBuffer: Number(v) || 0 })} numeric /></View>
    <Title eyebrow="BUDGET BY SUBCATEGORY" title="Build the cycle from below." />
    {budgetCategories.map((group) => { const groupBudget = categoryBudget(group.name); const groupSpent = catSpend[group.name] || 0; return <View key={group.id} style={s.budgetCategoryCard}><View style={s.budgetCategoryHead}><View style={{ flex: 1 }}><Text style={s.budgetCategoryName}>{group.icon}  {group.name}</Text><Text style={s.budgetCategoryMeta}>{money(groupSpent)} spent this cycle</Text></View><View style={s.budgetCategoryTotal}><Text style={s.budgetCategoryAmount}>{money(groupBudget)}</Text><Text style={s.budgetCategoryLabel}>CATEGORY BUDGET</Text></View></View>{group.subcategories.map((sub) => { const key = budgetKey(group.name, sub); const limit = state.subcategoryBudgets[key] || 0; const used = subcategorySpend[key] || 0; const percent = limit ? used / limit * 100 : 0; return <TouchableOpacity key={sub} style={s.subBudgetRow} onPress={() => openBudgetEditor(group.name, sub)}><View style={s.subBudgetTop}><View style={{ flex: 1 }}><Text style={s.subBudgetName}>{sub}</Text><Text style={s.subBudgetSpent}>{money(used)} spent</Text></View><Text style={[s.subBudgetLimit, !limit && { color: C.muted }]}>{limit ? money(limit) : 'SET BUDGET'}</Text><Ionicons name="chevron-forward" size={15} color={C.muted} /></View>{limit > 0 && <View style={s.subBudgetTrack}><View style={[s.subBudgetFill, { width: `${Math.min(100, percent)}%`, backgroundColor: percent > 100 ? C.coral : C.blue }]} /></View>}</TouchableOpacity>; })}</View>; })}
    <View style={s.card}><Text style={s.cardTitle}>Cash reality</Text><Text style={[s.realityNumber, trueSpendable < 0 && { color: C.coral }]}>{trueSpendable < 0 ? '− ' : ''}{money(trueSpendable)}</Text><View style={s.grid}><Mini label="LIQUID" value={cash} /><Mini label="CARD OWED" value={-cardDebt} /><Mini label="BUFFER" value={-state.safetyBuffer} /></View></View>
    <Title eyebrow="FIXED COMMITMENTS" title="Expected before payday." />
    <View style={s.expectedCard}><View style={s.expectedHero}><View><Text style={s.expectedEyebrow}>EXPECTED THIS CYCLE</Text><Text style={s.expectedTotal}>{money(bluecoins?.monthly.expectedFixedCommitments.total || 0)}</Text></View><View style={s.expectedRight}><Text style={s.expectedRemaining}>{money(bluecoins?.monthly.expectedFixedCommitments.remaining || 0)}</Text><Text style={s.expectedRemainingLabel}>STILL EXPECTED</Text></View></View><View style={s.expectedStats}><Text style={s.expectedStat}>Paid now · <Text style={s.expectedStatStrong}>{money(bluecoins?.monthly.expectedFixedCommitments.paid || 0)}</Text></Text><Text style={s.expectedStat}>{bluecoins?.monthly.expectedFixedCommitments.items.length || 0} recurring items</Text></View>{bluecoins?.monthly.expectedFixedCommitments.items.map((commitment) => <View key={commitment.key} style={s.expectedRow}><View style={[s.expectedStatus, commitment.status === 'paid' && s.expectedStatusPaid]}><Ionicons name={commitment.status === 'paid' ? 'checkmark' : 'time-outline'} size={13} color={commitment.status === 'paid' ? '#168A65' : C.coral} /></View><View style={{ flex: 1 }}><Text style={s.expectedName}>{commitment.label.split(' | ').pop()}</Text><Text style={s.expectedMeta}>{commitment.label.split(' | ')[0]} · last paid {commitment.lastUsed}</Text></View><View style={s.expectedAmounts}><Text style={s.expectedAmount}>{money(commitment.expectedAmount)}</Text><Text style={[s.expectedState, commitment.status === 'paid' && { color: '#168A65' }]}>{commitment.status === 'paid' ? `PAID ${money(commitment.currentAmount)}` : 'DUE'}</Text></View></View>)}{!bluecoins?.monthly.expectedFixedCommitments.items.length && <Empty text="Pick recurring items in Budget Coach to build this list." />}</View>
    <Title eyebrow="SPENDING GUARDS" title="Boundaries before regret." /><View style={s.ruleGrid}>{bluecoins?.spendingGuards.map((guard) => <View key={guard.id} style={[s.ruleCard, guard.level === 'danger' && { borderColor: C.coral }]}><Text style={s.accountType}>{guard.scope.toUpperCase()}</Text><Text style={s.ruleName}>{guard.name}</Text><Text style={s.rulePct}>{guard.percent.toFixed(0)}%</Text><Text style={s.entryMeta}>{money(guard.spent)} / {money(guard.limit)}</Text><View style={s.budgetTrack}><View style={[s.budgetFill, { width: `${Math.min(100, guard.percent)}%` }]} /></View></View>)}</View></>;
  const Reports = () => <><Title eyebrow="REPORTS" title="Patterns, not vibes." /><View style={s.grid}><Stat label="INCOME" value={income} color={C.mint} /><Stat label="EXPENSE" value={spent} color={C.coral} /><Stat label="NET" value={income - spent} color={C.blue} /></View><View style={s.card}><Text style={s.cardTitle}>Top categories · salary cycle</Text>{topCats.map(([name, value], index) => <View key={name} style={s.reportRow}><Text style={s.reportName}>{index + 1}. {name}</Text><View style={s.reportTrack}><View style={[s.reportFill, { width: `${spent ? Math.min(100, value / spent * 100) : 0}%` }]} /></View><Text style={s.reportValue}>{money(value)}</Text></View>)}{!topCats.length && <Empty text="Reports wake up after your first expense." />}</View></>;

  return <SafeAreaView style={s.safe}><View style={s.header}><TouchableOpacity onPress={() => navigation.navigate('Home')} style={s.back}><Ionicons name="arrow-back" size={21} color={C.ink} /></TouchableOpacity><View style={{ flex: 1 }}><Text style={s.brand}>REDCOINS</Text><Text style={s.source}>{state.importedSource ? `Structure seeded from ${state.importedSource}` : 'LeanLog money room'}</Text></View><TouchableOpacity style={s.headerAdd} onPress={() => resetEntry()}><Ionicons name="add" size={24} color={C.white} /></TouchableOpacity></View>
    {section === 'activity' ? <View style={s.activityBody}>{activityHeader}<View style={s.ledgerCard}><SectionList
      sections={activitySections}
      keyExtractor={(entry) => entry.id}
      renderItem={({ item: entry }) => <EntryRow entry={entry} accountBalance={entryBalanceById.get(entry.id)} selected={selectedSet.has(entry.id)} onPress={selectedIds.length ? () => toggleSelected(entry) : () => editEntry(entry)} onLong={() => toggleSelected(entry)} />}
      renderSectionHeader={({ section }) => <View style={s.ledgerDate}><Text style={s.ledgerDateText}>{section.title}</Text><Text style={[s.ledgerDayTotal, section.total > 0 && { color: '#168A65' }]}>{section.total > 0 ? '+' : section.total < 0 ? '− ' : ''}{money(section.total)}</Text></View>}
      extraData={selectedIds}
      initialNumToRender={16}
      maxToRenderPerBatch={16}
      updateCellsBatchingPeriod={32}
      windowSize={7}
      removeClippedSubviews
      keyboardShouldPersistTaps="always"
      keyboardDismissMode="on-drag"
      ListEmptyComponent={<Empty text="No matching RedCoins entries." />}
      showsVerticalScrollIndicator={false}
      stickySectionHeadersEnabled
      contentContainerStyle={!filtered.length ? s.emptyLedger : s.ledgerContent}
    /></View></View> : <ScrollView contentContainerStyle={s.body} showsVerticalScrollIndicator={false}>{section === 'home' ? <Home /> : section === 'accounts' ? <Accounts /> : section === 'plan' ? <Plan /> : <Reports />}</ScrollView>}
    {filterModal}<View style={s.nav}>{(['home', 'activity', 'accounts', 'plan', 'reports'] as Section[]).map((name) => <TouchableOpacity key={name} style={[s.navButton, section === name && s.navActive]} onPress={() => setSection(name)}><Ionicons name={({ home: 'grid', activity: 'list', accounts: 'wallet', plan: 'shield-checkmark', reports: 'bar-chart' } as any)[name]} size={18} color={section === name ? C.white : '#8993A6'} /><Text style={[s.navText, section === name && { color: C.white }]}>{name[0].toUpperCase() + name.slice(1)}</Text></TouchableOpacity>)}</View>
    <EntryModal visible={entryOpen} editing={!!editingEntryId} onDelete={deleteEditingEntry} close={() => setEntryOpen(false)} {...{ item, setItem, amount, setAmount, type, setType, applyEntryType, account, setAccount, toAccount, setToAccount, category, setCategory, subcategory, setSubcategory, note, setNote, labels, setLabels, repeat, setRepeat, installments, setInstallments, advanced, setAdvanced, suggestions, chooseSuggestion, saveEntry, entryDate, setEntryDate, state }} />
    <BudgetModal visible={!!budgetEditor} target={budgetEditor} value={budgetDraft} setValue={setBudgetDraft} allocated={allocatedBudget} total={state.monthlyBudget} current={budgetEditor ? state.subcategoryBudgets[budgetKey(budgetEditor.category, budgetEditor.subcategory)] || 0 : 0} close={() => setBudgetEditor(null)} save={saveSubcategoryBudget} />
    <ManageModal visible={!!manageOpen} mode={manageOpen} close={() => setManageOpen(null)} state={state} draft={{ draftName, setDraftName, draftType, setDraftType, draftBalance, setDraftBalance, draftCategory, setDraftCategory, draftSub, setDraftSub, draftParent }} save={async () => { const next = { ...state, accounts: [...state.accounts], categories: state.categories.map((c) => ({ ...c, subcategories: [...c.subcategories] })) }; if (manageOpen === 'account') { if (!draftName.trim()) return; next.accounts.push({ id: `${Date.now()}`, name: draftName.trim(), type: draftType, balance: Number(draftBalance) || 0 }); } else if (manageOpen === 'category') { if (!draftCategory.trim() || !draftSub.trim()) return; next.categories.push({ id: `${Date.now()}`, name: draftCategory.trim(), icon: '●', subcategories: [draftSub.trim()] }); } else { const parent = next.categories.find((c) => c.name === draftParent); if (!parent || !draftSub.trim()) return; parent.subcategories.push(draftSub.trim()); } await persist(next); setManageOpen(null); }} />
  </SafeAreaView>;
}

function BudgetDonut({ segments, spent }: { segments: { name: string; value: number; color: string; percent: number }[]; spent: number }) {
  const radius = 42; const circumference = 2 * Math.PI * radius; let offset = 0;
  return <View style={s.donutWrap}><Svg width={108} height={108} viewBox="0 0 108 108"><Circle cx="54" cy="54" r={radius} stroke="#DED7CC" strokeWidth="18" fill="none" />{segments.map((segment) => { const length = spent ? segment.value / spent * circumference : 0; const dashOffset = -offset; offset += length; return <Circle key={segment.name} cx="54" cy="54" r={radius} stroke={segment.color} strokeWidth="18" fill="none" strokeDasharray={`${length} ${circumference}`} strokeDashoffset={dashOffset} rotation="-90" origin="54,54" />; })}</Svg><View style={s.donutCenter}><Text style={s.donutValue}>{money(spent)}</Text><Text style={s.donutLabel}>SPENT</Text></View></View>;
}
function Title({ eyebrow, title, action, onAction }: any) { return <View style={s.titleRow}><View style={{ flex: 1 }}><Text style={s.eyebrow}>{eyebrow}</Text><Text style={s.title}>{title}</Text></View>{action && <TouchableOpacity style={s.titleAction} onPress={onAction}><Text style={s.titleActionText}>{action}</Text></TouchableOpacity>}</View>; }
function Mini({ label, value }: any) { return <View style={s.mini}><Text style={s.miniValue}>{value < 0 ? '− ' : ''}{money(value)}</Text><Text style={s.miniLabel}>{label}</Text></View>; }
function Stat({ label, value, color }: any) { return <View style={s.stat}><Text style={s.statLabel}>{label}</Text><Text style={[s.statValue, { color }]}>{value < 0 ? '− ' : ''}{money(value)}</Text></View>; }
function PlanCell({ label, value }: any) { return <View style={s.planCell}><Text style={s.planLabel}>{label}</Text><Text style={s.planValue}>{value < 0 ? '− ' : ''}{money(value)}</Text></View>; }
function Empty({ text }: any) { return <Text style={s.empty}>{text}</Text>; }
const transactionIcon = (entry: RedCoinsEntry): any => {
  if (entry.type === 'transfer') return 'swap-horizontal';
  if (entry.type === 'income') return 'arrow-down';
  const label = `${entry.category} ${entry.subcategory}`.toLowerCase();
  if (/food|dining|jajan|makan|restaurant|water/.test(label)) return 'restaurant';
  if (/fuel|minyak|petrol|car|motor|engine/.test(label)) return 'car';
  if (/home|house|hardware|mortgage/.test(label)) return 'home';
  if (/health|medical|clinic/.test(label)) return 'medkit';
  if (/bill|utilities|electric|internet/.test(label)) return 'receipt';
  return 'wallet';
};
const EntryRow = memo(function EntryRow({ entry, accountBalance, onLong, onPress, selected }: { entry: RedCoinsEntry; accountBalance?: number; onLong?: () => void; onPress?: () => void; selected?: boolean }) { const color = entry.type === 'transfer' ? C.blue : entry.type === 'income' ? '#18A879' : C.coral; return <TouchableOpacity onPress={onPress} onLongPress={onLong} delayLongPress={350} style={[s.entry, selected && s.entrySelected]}><View style={[s.entryIcon, { backgroundColor: color }]}>{selected ? <Ionicons name="checkmark" size={15} color={C.white} /> : <Ionicons name={transactionIcon(entry)} size={14} color={C.white} />}</View><View style={s.entryMain}><Text style={s.entryName} numberOfLines={1}>{entry.item}</Text><Text style={s.entryMeta} numberOfLines={1}>{entryTime(entry.date)} · {entry.type === 'transfer' ? `From ${entry.account} → ${entry.toAccount || 'Unknown'}` : entry.subcategory}</Text></View><View style={s.entryRight}><Text style={[s.entryAmount, { color }]}>{entry.type === 'income' ? '+' : entry.type === 'transfer' ? '⇄ ' : '− '}{money(entry.amount)}</Text><Text style={s.entryAccount} numberOfLines={1}>{entry.account}{accountBalance != null ? ` · ${accountBalance < 0 ? '− ' : ''}${money(accountBalance)}` : ''}</Text></View></TouchableOpacity>; });
function Field({ label, value, onChange, numeric }: any) { return <View style={s.field}><Text style={s.fieldLabel}>{label}</Text><TextInput value={value} onChangeText={onChange} keyboardType={numeric ? 'numeric' : 'default'} style={s.fieldInput} /></View>; }

const LedgerSearch = memo(function LedgerSearch({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const [draft, setDraft] = useState(value);
  useEffect(() => { setDraft(value); }, [value]);
  useEffect(() => {
    if (draft === value) return;
    const timer = setTimeout(() => onChange(draft), 220);
    return () => clearTimeout(timer);
  }, [draft, value, onChange]);
  return <TextInput value={draft} onChangeText={setDraft} placeholder="Search item, category, account…" placeholderTextColor={C.muted} autoCorrect={false} autoCapitalize="none" returnKeyType="search" style={[s.search, { flex: 1 }]} />;
});

const LedgerFilterModal = memo(function LedgerFilterModal({ visible, current, accounts, categories, close, apply }: {
  visible: boolean;
  current: { type: 'all' | RedCoinsType; account: string; category: string; day: string };
  accounts: string[];
  categories: string[];
  close: () => void;
  apply: (next: { type: 'all' | RedCoinsType; account: string; category: string; day: string }) => void;
}) {
  const [draft, setDraft] = useState(current);
  useEffect(() => { if (visible) setDraft(current); }, [visible]);
  const clear = () => setDraft({ type: 'all', account: 'all', category: 'all', day: '' });
  return <Modal visible={visible} transparent animationType="slide" onRequestClose={close}><View style={s.sheetShade}><View style={s.selectionSheet}><View style={s.sheetGrab} /><View style={s.filterTitleRow}><Text style={s.sheetTitle}>Filter transactions</Text><TouchableOpacity onPress={clear}><Text style={s.clearFilterText}>CLEAR ALL</Text></TouchableOpacity></View>{draft.day ? <View style={s.activeDayFilter}><Text style={s.activeDayFilterText}>DATE · {draft.day}</Text><TouchableOpacity onPress={() => setDraft((value) => ({ ...value, day: '' }))}><Ionicons name="close-circle" size={17} color={C.coral} /></TouchableOpacity></View> : null}<Text style={s.inputLabel}>TYPE</Text><View style={s.typeRow}>{(['all', 'expense', 'income', 'transfer'] as const).map((value) => <Chip key={value} text={value.toUpperCase()} active={draft.type === value} onPress={() => setDraft((row) => ({ ...row, type: value }))} />)}</View><Text style={s.inputLabel}>ACCOUNT</Text><ScrollView horizontal>{['all', ...accounts].map((value) => <Chip key={value} text={value} active={draft.account === value} onPress={() => setDraft((row) => ({ ...row, account: value }))} />)}</ScrollView><Text style={s.inputLabel}>CATEGORY</Text><ScrollView horizontal>{['all', ...categories].map((value) => <Chip key={value} text={value} active={draft.category === value} onPress={() => setDraft((row) => ({ ...row, category: value }))} />)}</ScrollView><TouchableOpacity style={s.sheetSave} onPress={() => apply(draft)}><Text style={s.sheetSaveText}>APPLY FILTERS</Text></TouchableOpacity></View></View></Modal>;
});

function EntryModal(p: any) {
  const [picker, setPicker] = useState<'account' | 'destination' | 'category' | null>(null);
  const [pickerSearch, setPickerSearch] = useState('');
  const [datePickerMode, setDatePickerMode] = useState<'date' | 'time' | null>(null);
  const [suggestionOpen, setSuggestionOpen] = useState(true);
  const amountRef = useRef<TextInput>(null);
  useEffect(() => { if (p.visible) setSuggestionOpen(true); }, [p.visible]);
  const cats = p.state.categories;
  const openPicker = (value: typeof picker) => { setPickerSearch(''); setPicker(value); };
  const chooseTemplate = (entry: any) => { p.chooseSuggestion(entry); setSuggestionOpen(false); setTimeout(() => amountRef.current?.focus(), 60); };
  return <Modal visible={p.visible} animationType="slide" onRequestClose={p.close}>
    <SafeAreaView style={s.modal}>
      <View style={s.modalHead}><TouchableOpacity onPress={p.close}><Ionicons name="arrow-back" size={24} color={C.ink} /></TouchableOpacity><Text style={s.modalTitle}>{p.editing ? 'Edit entry' : 'New entry'}</Text><Text style={s.plusOne}>{p.editing ? 'EDIT' : '+1'}</Text></View>
      <ScrollView contentContainerStyle={s.modalBody} keyboardShouldPersistTaps="handled">
        <View style={s.typeRow}>{(['expense', 'income', 'transfer'] as RedCoinsType[]).map((x) => <TouchableOpacity key={x} onPress={() => p.applyEntryType(x)} style={[s.typeButton, p.type === x && { backgroundColor: x === 'expense' ? C.coral : x === 'income' ? '#379B73' : C.blue }]}><Text style={[s.typeText, p.type === x && { color: C.white }]}>{x.toUpperCase()}</Text></TouchableOpacity>)}</View>
        <TextInput style={s.itemInput} value={p.item} onChangeText={(value) => { p.setItem(value); setSuggestionOpen(true); }} onFocus={() => setSuggestionOpen(true)} onSubmitEditing={() => amountRef.current?.focus()} returnKeyType="next" autoFocus={!p.editing} selectTextOnFocus placeholder="Name" placeholderTextColor="#AAA393" />
        {suggestionOpen && p.suggestions.length > 0 && <View style={s.suggestions}><Text style={s.templateLabel}>{p.item.trim() ? 'SMART MATCHES' : 'RECENT & FREQUENT'}</Text>{p.suggestions.map((x: any) => <TouchableOpacity key={x.id} onPress={() => chooseTemplate(x)} style={s.suggestion}><View style={{ flex: 1 }}><Text style={s.suggestionName}>{x.item}</Text><Text style={s.suggestionMeta}>{x.category} · {x.subcategory} · {x.account}{x.usageCount > 1 ? ` · used ${x.usageCount}×` : ''}</Text></View><Text style={s.suggestionPrice}>{money(x.amount)}</Text></TouchableOpacity>)}</View>}
        <TouchableOpacity style={s.entryDateButton} onPress={() => setDatePickerMode('date')} activeOpacity={0.75}><Ionicons name="time-outline" size={15} color={C.ink} /><Text style={s.entryDateButtonText}>{p.entryDate.toLocaleString('en-MY', { dateStyle: 'medium', timeStyle: 'short' }).toUpperCase()}</Text><Ionicons name="calendar-outline" size={14} color={C.ink} /></TouchableOpacity>
        <View style={s.amountWrap}><View style={[s.amountSign, { backgroundColor: p.type === 'expense' ? C.coral : p.type === 'income' ? '#379B73' : C.blue }]}><Text style={s.amountSignText}>{p.type === 'expense' ? '−' : p.type === 'income' ? '+' : '⇄'}</Text></View><TextInput ref={amountRef} style={s.amountBare} value={p.amount} onChangeText={p.setAmount} keyboardType="decimal-pad" returnKeyType="done" onSubmitEditing={p.saveEntry} selectTextOnFocus placeholder="0.00" placeholderTextColor="#AAA393" /><Text style={s.currency}>MYR</Text></View>
        {p.type !== 'transfer' && <PickerRow icon="grid-outline" label="CATEGORY" value={`${cats.find((c: any) => c.name === p.category)?.icon || '●'}  ${p.subcategory || p.category}`} onPress={() => openPicker('category')} />}
        <PickerRow icon="wallet-outline" label={p.type === 'transfer' ? 'FROM ACCOUNT' : 'ACCOUNT'} value={p.account || 'Choose account'} onPress={() => openPicker('account')} />
        {p.type === 'transfer' && <PickerRow icon="arrow-forward-circle-outline" label="TRANSFER TO" value={p.toAccount || 'Choose destination'} onPress={() => openPicker('destination')} />}
        <TouchableOpacity style={s.advancedButton} onPress={() => p.setAdvanced(!p.advanced)}><Text style={s.advancedText}>Split · Status · Labels · Repeat</Text><Ionicons name={p.advanced ? 'chevron-up' : 'chevron-down'} size={17} color={C.muted} /></TouchableOpacity>
        {p.advanced && <View style={s.advancedBox}><Field label="LABELS" value={p.labels} onChange={p.setLabels} /><Text style={s.inputLabel}>REPEAT</Text><View style={s.typeRow}>{['none', 'weekly', 'monthly', 'installment'].map((x) => <TouchableOpacity key={x} onPress={() => p.setRepeat(x)} style={[s.repeatButton, p.repeat === x && s.repeatActive]}><Text style={s.repeatText}>{x}</Text></TouchableOpacity>)}</View>{p.repeat === 'installment' && <Field label="NUMBER OF INSTALMENTS" value={p.installments} onChange={p.setInstallments} numeric />}</View>}
        <TextInput style={s.noteInput} value={p.note} onChangeText={p.setNote} placeholder="Note" placeholderTextColor={C.muted} multiline />
      </ScrollView>
      <View style={s.entryFooter}>{p.editing && <TouchableOpacity style={s.entryDelete} onPress={p.onDelete}><Text style={s.entryDeleteText}>DELETE</Text></TouchableOpacity>}<TouchableOpacity style={[s.entrySave, { flex: 1, backgroundColor: p.type === 'expense' ? C.coral : p.type === 'income' ? '#379B73' : C.blue }]} onPress={p.saveEntry}><Ionicons name="save-outline" size={19} color="#FFF" /><Text style={s.entrySaveText}>{p.editing ? `UPDATE ${p.type.toUpperCase()}` : `SAVE ${p.type.toUpperCase()}`}</Text></TouchableOpacity></View>
      {datePickerMode && <DateTimePicker value={p.entryDate} mode={datePickerMode} onChange={(_: any, selected?: Date) => {
        if (!selected) { setDatePickerMode(null); return; }
        const merged = new Date(p.entryDate);
        if (datePickerMode === 'date') {
          merged.setFullYear(selected.getFullYear(), selected.getMonth(), selected.getDate()); p.setEntryDate(merged); setDatePickerMode('time');
        } else {
          merged.setHours(selected.getHours(), selected.getMinutes(), 0, 0); p.setEntryDate(merged); setDatePickerMode(null);
        }
      }} />}
      <SelectionSheet visible={!!picker} close={() => setPicker(null)} search={pickerSearch} setSearch={setPickerSearch} title={picker === 'category' ? 'Choose category' : picker === 'destination' ? 'Transfer to' : 'Choose account'}>
        {picker === 'category' ? cats.map((group: any) => { const matches = group.subcategories.filter((sub: string) => `${group.name} ${sub}`.toLowerCase().includes(pickerSearch.toLowerCase())); return matches.length ? <View key={group.id}><Text style={s.pickerGroup}>{group.name}</Text><View style={s.categoryGrid}>{matches.map((sub: string) => <TouchableOpacity key={sub} style={s.categoryChoice} onPress={() => { p.setCategory(group.name); p.setSubcategory(sub); setPicker(null); }}><View style={s.categoryIcon}><Text>{group.icon}</Text></View><Text style={s.categoryChoiceText}>{sub}</Text></TouchableOpacity>)}</View></View> : null; }) : p.state.accounts.filter((a: any) => a.name.toLowerCase().includes(pickerSearch.toLowerCase()) && (picker !== 'destination' || a.name !== p.account)).map((a: any) => <TouchableOpacity key={a.id} style={s.accountChoice} onPress={() => { picker === 'destination' ? p.setToAccount(a.name) : p.setAccount(a.name); setPicker(null); }}><View><Text style={s.accountChoiceName}>{a.name}</Text><Text style={s.accountChoiceType}>{a.type}</Text></View><Text style={[s.accountChoiceBalance, a.balance < 0 && { color: C.coral }]}>{a.balance < 0 ? '− ' : ''}{money(a.balance)}</Text></TouchableOpacity>)}
      </SelectionSheet>
    </SafeAreaView>
  </Modal>;
}
function PickerRow({ icon, label, value, onPress }: any) { return <TouchableOpacity style={s.pickerRow} onPress={onPress}><View style={s.pickerRowIcon}><Ionicons name={icon} size={19} color={C.ink} /></View><View style={{ flex: 1 }}><Text style={s.pickerRowLabel}>{label}</Text><Text style={s.pickerRowValue}>{value}</Text></View><Ionicons name="chevron-forward" size={18} color={C.muted} /></TouchableOpacity>; }
function SelectionSheet({ visible, close, search, setSearch, title, children }: any) { return <Modal visible={visible} transparent animationType="slide" onRequestClose={close}><View style={s.sheetShade}><View style={s.selectionSheet}><View style={s.sheetGrab} /><View style={s.selectionTop}><TextInput value={search} onChangeText={setSearch} placeholder={`Search ${title.toLowerCase()}…`} placeholderTextColor={C.muted} style={s.selectionSearch} /><TouchableOpacity style={s.selectionDone} onPress={close}><Text style={s.selectionDoneText}>DONE</Text></TouchableOpacity></View><ScrollView keyboardShouldPersistTaps="handled">{children}</ScrollView></View></View></Modal>; }
